import org.springframework.stereotype.Repository;

/**
 * The rates for each grade on each sheet, each in force from its from-date (null: from the beginning
 * of time), through its to-date (null: with no end). A grade without one in force on a date has no rate on
 * that date on the sheet itself; then its parent's rate on that date is used, then the parent's parent's, up to
 * three levels up (see {@link #chain}).
 */
@Repository
public class RateRepository {

    private static final RowMapper<Rate> ROW = (rs, n) -> {
        Date from = rs.getDate("from_date");
        Date to = rs.getDate("to_date");
        return new Rate(rs.getString("sheet_id"), rs.getString("grade"), rs.getBigDecimal("rate"),
                from == null ? null : from.toLocalDate(), to == null ? null : to.toLocalDate(), rs.getInt("version"),
                rs.getObject("after_seq", Long.class));
    };

    /** How many levels of parents a sheet takes rates from. */
    public static final int PARENT_LEVELS = 3;

    private final JdbcTemplate jdbc;

    public RateRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's rates, by grade, then by from-date (none first), each with its older versions, newest first. */
    public List<Rate> list(String sheetId) {
        List<Rate> versions = jdbc.query("SELECT sheet_id, grade, rate, from_date, to_date, version, after_seq FROM rate_version"
                + " WHERE sheet_id = ? ORDER BY version DESC, id DESC", ROW, sheetId);
        return jdbc.query("SELECT sheet_id, grade, rate, from_date, to_date, version, after_seq FROM rate WHERE sheet_id = ?"
                + " ORDER BY grade, from_date NULLS FIRST", ROW, sheetId).stream()
                .map(r -> r.withEarlier(versions.stream().filter(v -> v.grade().equals(r.grade())
                        && java.util.Objects.equals(v.from(), r.from())).toList()))
                .toList();
    }

    /** A sheet's parent's rates as they stood when a child of it was snapshotted (see SheetHistory#snapshot), as
     *  {@link #list} lists them. */
    public List<Rate> listParentSnapshotted(long snapshotId, String sheetId) {
        List<Rate> versions = jdbc.query("SELECT sheet_id, grade, rate, from_date, to_date, version, after_seq FROM hist.parent_rate_version"
                + " WHERE snapshot_id = ? AND sheet_id = ? ORDER BY version DESC, id DESC", ROW, snapshotId, sheetId);
        return jdbc.query("SELECT sheet_id, grade, rate, from_date, to_date, version, after_seq FROM hist.parent_rate"
                + " WHERE snapshot_id = ? AND sheet_id = ? ORDER BY grade, from_date NULLS FIRST", ROW, snapshotId, sheetId).stream()
                .map(r -> r.withEarlier(versions.stream().filter(v -> v.grade().equals(r.grade())
                        && java.util.Objects.equals(v.from(), r.from())).toList()))
                .toList();
    }

    /** The sheet, then its parent, its parent's parent, and so on up to {@link #PARENT_LEVELS} levels up. */
    public List<String> ancestry(String sheetId) {
        List<String> found = new java.util.ArrayList<>(List.of(sheetId));
        String at = sheetId;
        while (found.size() <= PARENT_LEVELS) {
            String parent = parentOf(at);
            if (parent == null || found.contains(parent)) {
                break;
            }
            found.add(parent);
            at = parent;
        }
        return found;
    }

    /** The sheet's parent; null when it has none. */
    public String parentOf(String sheetId) {
        return jdbc.query("SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = 'parent'",
                (rs, n) -> rs.getString(1), sheetId).stream().filter(java.util.Objects::nonNull).findFirst().orElse(null);
    }

    /** The sheets naming this one as their parent, by id. */
    public List<String> childrenOf(String sheetId) {
        return jdbc.query("SELECT sheet_id FROM sheet_setting WHERE setting_key = 'parent' AND setting_value = ?"
                + " ORDER BY sheet_id", (rs, n) -> rs.getString(1), sheetId);
    }

    /** The sheet's children, their children, and so on down (each once, the sheet itself never among them). */
    public List<String> descendantsOf(String sheetId) {
        List<String> found = new java.util.ArrayList<>();
        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
        while (!todo.isEmpty()) {
            for (String child : childrenOf(todo.poll())) {
                if (seen.add(child)) {
                    found.add(child);
                    todo.add(child);
                }
            }
        }
        return found;
    }

    /** The sheet's own rates (level 0), then each of its parents' (see {@link #ancestry}), each at its level up. */
    public List<Rate> chain(String sheetId) {
        List<String> sheets = ancestry(sheetId);
        List<Rate> found = new java.util.ArrayList<>();
        for (int level = 0; level < sheets.size(); level++) {
            int at = level;
            list(sheets.get(level)).forEach(r -> found.add(r.at(at)));
        }
        return found;
    }

    /**
     * The grade's rate in force on the date, on the sheet or else (none in force there) up its parents (see
     * {@link #ancestry}); null when none has one.
     */
    public BigDecimal find(String sheetId, String grade, LocalDate on) {
        for (String sheet : ancestry(sheetId)) {
            BigDecimal rate = findOwn(sheet, grade, on);
            if (rate != null) {
                return rate;
            }
        }
        return null;
    }

    /**
     * The grade's rate on the date for a claim added at {@code added} (see {@link Rate#forClaim}): a forward-only rate
     * saved after the claim was added does not apply to it. On the sheet or else up its parents; null when none has one.
     */
    public BigDecimal find(String sheetId, String grade, LocalDate on, Long added) {
        return Rate.on(chain(sheetId), grade, on, added);
    }

    /**
     * The grade's rate in force on the date on the sheet itself: the one with the latest from-date on or before it, a rate
     * without a from-date counting as the earliest. Null when none applies, or the date is after that one's to-date.
     */
    public BigDecimal findOwn(String sheetId, String grade, LocalDate on) {
        return jdbc.query("SELECT sheet_id, grade, rate, from_date, to_date, version, after_seq FROM rate WHERE sheet_id = ? AND grade = ?"
                + " AND (from_date IS NULL OR from_date <= ?) ORDER BY from_date DESC NULLS LAST LIMIT 1", ROW,
                sheetId, grade, Date.valueOf(on)).stream().findFirst()
                .filter(r -> r.to() == null || !r.to().isBefore(on)).map(Rate::rate).orElse(null);
    }

    /**
     * Set a grade's rate from a date (null: from the beginning of time) through a to-date (null: with no end). One
     * already there for that from-date is kept as an older version, and the new one becomes the next version. Saved
     * with a from-date on or after the sheet's {@code today}, it is forward-only: it applies only to claims added after
     * it (see {@link Rate#forClaim}).
     */
    public Rate set(String sheetId, String grade, BigDecimal rate, LocalDate from, LocalDate to, LocalDate today) {
        Date fromDate = from == null ? null : Date.valueOf(from);
        Long after = from != null && !from.isBefore(today)
                ? jdbc.queryForObject("SELECT NEXT VALUE FOR change_seq", Long.class) : null;
        Rate old = jdbc.query("SELECT sheet_id, grade, rate, from_date, to_date, version, after_seq FROM rate WHERE sheet_id = ?"
                + " AND grade = ? AND from_date IS NOT DISTINCT FROM ?", ROW, sheetId, grade, fromDate)
                .stream().findFirst().orElse(null);
        int version = 1;
        if (old != null) {
            jdbc.update("INSERT INTO rate_version (sheet_id, grade, from_date, version, rate, to_date, after_seq)"
                    + " VALUES (?, ?, ?, ?, ?, ?, ?)", sheetId, grade, fromDate, old.version(), old.rate(),
                    old.to() == null ? null : Date.valueOf(old.to()), old.after());
            version = old.version() + 1;
        }
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                sheetId, grade, fromDate);
        jdbc.update("INSERT INTO rate (sheet_id, grade, rate, from_date, to_date, version, after_seq) VALUES (?, ?, ?, ?, ?, ?, ?)",
                sheetId, grade, rate, fromDate, to == null ? null : Date.valueOf(to), version, after);
        return new Rate(sheetId, grade, rate, from, to, version, after);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** A grade's rate on a sheet: a percent with two decimals, in force from a date (null: from the beginning of time)
 * through a to-date (null: with no end). Its level is how far up the sheet's parents it was found: 0 on the sheet itself,
 * 1 on its parent, and so on. Its version counts how many times it has been set for its grade and from-date; it
 * is always the newest version, the one in force. A forward-only rate (saved with a from-date on or after the sheet's
 * today) carries {@code after}: it applies only to claims added after it (see {@link #forClaim}); null for one that
 * applies to every claim. {@code earlier} holds its older versions, newest first, for the claims it does not apply to. */
public record Rate(String sheetId, String grade, BigDecimal rate, LocalDate from, LocalDate to, int level, int version,
        Long after, List<Rate> earlier) {

    public Rate(String sheetId, String grade, BigDecimal rate, LocalDate from, LocalDate to) {
        this(sheetId, grade, rate, from, to, 0, 1, null, List.of());
    }

    public Rate(String sheetId, String grade, BigDecimal rate, LocalDate from, LocalDate to, int version, Long after) {
        this(sheetId, grade, rate, from, to, 0, version, after, List.of());
    }

    /** The rate as found the given number of levels up. */
    public Rate at(int level) {
        return new Rate(sheetId, grade, rate, from, to, level, version, after, earlier.stream().map(e -> e.at(level)).toList());
    }

    /** The rate with its older versions, newest first. */
    public Rate withEarlier(List<Rate> versions) {
        return new Rate(sheetId, grade, rate, from, to, level, version, after, versions);
    }

    /** Whether this version applies to a claim added at {@code added} (null: before every forward-only rate). */
    public boolean appliesTo(Long added) {
        return after == null || (added != null && added > after);
    }

    /**
     * The rates as they apply to a claim added at {@code added}: each rate whose newest version applies to it, else its
     * newest older version that does; a rate none of whose versions applies is left out.
     */
    public static List<Rate> forClaim(List<Rate> rates, Long added) {
        List<Rate> found = new ArrayList<>();
        for (Rate r : rates) {
            if (r.appliesTo(added)) {
                found.add(r);
                continue;
            }
            r.earlier().stream().filter(e -> e.appliesTo(added)).findFirst().ifPresent(found::add);
        }
        return found;
    }

    /**
     * The grade's rate in force on the date among rates of several levels: the sheet's own, else (no rate of its own in
     * force then) its parent's, and so on up. On each level, the latest from-date on or before it, none counting as the
     * earliest; none when the date is after that rate's to-date.
     */
    public static BigDecimal on(java.util.List<Rate> rates, String grade, LocalDate on) {
        int top = rates.stream().mapToInt(Rate::level).max().orElse(0);
        for (int level = 0; level <= top; level++) {
            Rate found = null;
            for (Rate r : rates) {
                if (r.level() != level || !r.grade().equals(grade) || (r.from() != null && r.from().isAfter(on))) {
                    continue;
                }
                if (found == null || (r.from() != null && (found.from() == null || r.from().isAfter(found.from())))) {
                    found = r;
                }
            }
            if (found != null && (found.to() == null || !found.to().isBefore(on))) {
                return found.rate();
            }
        }
        return null;
    }

    /** The grade's rate in force on the date for a claim added at {@code added} (see {@link #forClaim}). */
    public static BigDecimal on(List<Rate> rates, String grade, LocalDate on, Long added) {
        return on(forClaim(rates, added), grade, on);
    }
}
package net.officefloor.hq.app.sheet;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * Copies a sheet to a sheet id never used: its today, settings, roles, rates, holidays, void reasons, templates, the
 * tags ever used on its claims, its people (grades, terms, contacts, aliases, holds, retirements, patrons), its pools, its crews,
 * its plans (with the dates they made claims for), its periods (all open, with no figures fixed) and its claims (status, frozen figures, dates, notes, logs, lines). Its
 * statements are not copied (no claim is bound), nor its snapshots, watches, delegations, comments, editor locks or
 * settle batches.
 */
@Repository
public class SheetCloneRepository {

    private final JdbcTemplate jdbc;

    public SheetCloneRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Create the clone with everything but its claims; answers the clone's person id for each person's id. */
    public Map<Long, Long> copySheet(String from, String to) {
        jdbc.update("INSERT INTO sheet (id, today, last_claim_listed) SELECT ?, today, last_claim_listed FROM sheet"
                + " WHERE id = ?", to, from);
        jdbc.update("INSERT INTO sheet_setting (sheet_id, setting_key, setting_value) SELECT ?, setting_key,"
                + " setting_value FROM sheet_setting WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value) SELECT ?,"
                + " setting_key, from_date, setting_value FROM sheet_setting_from WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO sheet_role (sheet_id, user_name, role) SELECT ?, user_name, role FROM sheet_role"
                + " WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO rate (sheet_id, grade, rate, from_date, to_date, version, after_seq) SELECT ?, grade, rate,"
                + " from_date, to_date, version, after_seq FROM rate WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO rate_version (sheet_id, grade, from_date, version, rate, to_date, after_seq) SELECT ?, grade,"
                + " from_date, version, rate, to_date, after_seq FROM rate_version WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO holiday (sheet_id, holiday_date) SELECT ?, holiday_date FROM holiday"
                + " WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO void_reason (sheet_id, reason) SELECT ?, reason FROM void_reason"
                + " WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO claim_template (sheet_id, name, amount, note) SELECT ?, name, amount, note"
                + " FROM claim_template WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO claim_tag (sheet_id, tag) SELECT ?, tag FROM claim_tag WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, claim_cap) SELECT ?, name, from_date, to_date, claim_cap"
                + " FROM period WHERE sheet_id = ? ORDER BY id", to, from);

        Map<Long, Long> people = new HashMap<>();
        for (Long id : ids("SELECT id FROM person WHERE sheet_id = ? ORDER BY id", from)) {
            long copy = jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO person (sheet_id, name, version,"
                    + " retired_from, terms, contact, tags, list_position, origin, flag_reason, flag_until) SELECT ?, name, 0, retired_from, terms,"
                    + " contact, tags, list_position, origin, flag_reason, flag_until FROM person WHERE id = ?)", Long.class, to, id);
            people.put(id, copy);
            jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) SELECT ?, grade, from_date"
                    + " FROM person_grade WHERE person_id = ?", copy, id);
            jdbc.update("INSERT INTO person_terms (person_id, terms, from_date) SELECT ?, terms, from_date"
                    + " FROM person_terms WHERE person_id = ?", copy, id);
            jdbc.update("INSERT INTO person_hold (person_id, from_date, to_date) SELECT ?, from_date, to_date"
                    + " FROM person_hold WHERE person_id = ? ORDER BY id", copy, id);
            jdbc.update("INSERT INTO person_retirement (person_id, from_date, to_date) SELECT ?, from_date, to_date"
                    + " FROM person_retirement WHERE person_id = ? ORDER BY id", copy, id);
            jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) SELECT ?, ?, alias FROM person_alias"
                    + " WHERE person_id = ? ORDER BY id", to, copy, id);
        }
        for (Map<String, Object> patron : jdbc.queryForList("SELECT pp.person_id, pp.patron_id FROM person_patron pp"
                + " JOIN person q ON q.id = pp.person_id WHERE q.sheet_id = ? ORDER BY pp.named", from)) {
            Long person = people.get(((Number) patron.get("person_id")).longValue());
            Long named = people.get(((Number) patron.get("patron_id")).longValue());
            if (person != null && named != null) {
                jdbc.update("INSERT INTO person_patron (person_id, patron_id) VALUES (?, ?)", person, named);
            }
        }

        Map<Long, Long> pools = new HashMap<>();
        for (Long id : ids("SELECT id FROM pool WHERE sheet_id = ? ORDER BY id", from)) {
            pools.put(id, jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO pool (sheet_id, name)"
                    + " SELECT ?, name FROM pool WHERE id = ?)", Long.class, to, id));
        }
        for (Map<String, Object> member : jdbc.queryForList("SELECT pool_id, person_id, member_pool_id, share,"
                + " from_date, to_date FROM pool_member WHERE sheet_id = ? ORDER BY id", from)) {
            jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, person_id, member_pool_id, share, from_date,"
                    + " to_date) VALUES (?, ?, ?, ?, ?, ?, ?)", to, pools.get(id(member.get("pool_id"))),
                    people.get(id(member.get("person_id"))), pools.get(id(member.get("member_pool_id"))),
                    member.get("share"), member.get("from_date"), member.get("to_date"));
        }
        Map<Long, Long> crews = new HashMap<>();
        for (Map<String, Object> crew : jdbc.queryForList("SELECT id, name, lead_id FROM crew WHERE sheet_id = ? ORDER BY id",
                from)) {
            crews.put(id(crew.get("id")), jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO crew (sheet_id, name,"
                    + " lead_id) VALUES (?, ?, ?))", Long.class, to, crew.get("name"), people.get(id(crew.get("lead_id")))));
        }
        for (Map<String, Object> member : jdbc.queryForList("SELECT crew_id, person_id FROM crew_member WHERE sheet_id = ?"
                + " ORDER BY id", from)) {
            jdbc.update("INSERT INTO crew_member (sheet_id, crew_id, person_id) VALUES (?, ?, ?)", to,
                    crews.get(id(member.get("crew_id"))), people.get(id(member.get("person_id"))));
        }
        for (Long id : ids("SELECT id FROM plan WHERE sheet_id = ? ORDER BY id", from)) {
            Long person = jdbc.queryForObject("SELECT person_id FROM plan WHERE id = ?", Long.class, id);
            long copy = jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO plan (sheet_id, person_id, amount,"
                    + " start_date, every_days, month_day, end_date) SELECT ?, ?, amount, start_date, every_days, month_day,"
                    + " end_date FROM plan"
                    + " WHERE id = ?)", Long.class, to, people.get(person), id);
            jdbc.update("INSERT INTO plan_claim (sheet_id, plan_id, plan_date) SELECT ?, ?, plan_date FROM plan_claim"
                    + " WHERE plan_id = ? ORDER BY id", to, copy, id);
        }
        return people;
    }

    /**
     * Copy the sheet's claims, each with its log and lines, to the clone's people: a claim that had a number takes its new one
     * from {@code numbers} (by claim id), and a correction or split names its claim by the new number.
     */
    public void copyClaims(String from, String to, Map<Long, Long> people, Map<Long, String> numbers) {
        List<Map<String, Object>> claims = jdbc.queryForList(
                "SELECT id, person_id, claim_number, corrects, split_from FROM claim WHERE sheet_id = ? ORDER BY id", from);
        Map<String, String> renumbered = new HashMap<>();
        for (Map<String, Object> claim : claims) {
            if (claim.get("claim_number") != null) {
                renumbered.put((String) claim.get("claim_number"), numbers.get(id(claim.get("id"))));
            }
        }
        for (Map<String, Object> claim : claims) {
            long id = id(claim.get("id"));
            long copy = jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO claim (sheet_id, person_id,"
                    + " amount, claim_date, note, status, claim_number, settled_due, opened_by, stated, stated_due,"
                    + " corrects, listed, deferred_until, proofs, proofs_photo, split_from, late_entry, reminded_on, escalated, waived, held, due_from, terms,"
                    + " ref, tags, void_reason, edited_by, due_by, settle_batch, added_seq)"
                    + " SELECT ?, ?, amount, claim_date, note, status, ?, settled_due, opened_by, FALSE, NULL,"
                    + " ?, listed, deferred_until, proofs, proofs_photo, ?, late_entry, reminded_on, escalated, waived, held, due_from, terms,"
                    + " ref, tags, void_reason, edited_by, due_by, NULL, added_seq FROM claim WHERE id = ?)", Long.class,
                    to, people.get(id(claim.get("person_id"))), numbers.get(id), renumbered.get((String) claim.get("corrects")),
                    renumbered.get((String) claim.get("split_from")), id);
            jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, logged_on, due) SELECT ?, ?,"
                    + " status, by_user, logged_on, due FROM claim_log WHERE claim_id = ? ORDER BY id", to, copy, id);
            jdbc.update("INSERT INTO claim_line (sheet_id, claim_id, label, qty, unit) SELECT ?, ?, label, qty, unit"
                    + " FROM claim_line WHERE claim_id = ? ORDER BY id", to, copy, id);
        }
    }

    private List<Long> ids(String sql, String sheetId) {
        return jdbc.queryForList(sql, Long.class, sheetId);
    }

    private static Long id(Object value) {
        return value == null ? null : ((Number) value).longValue();
    }
}

